<div class="page-title clearfix"><h1><?php echo esc($warehouse->name); ?> <span class="badge bg-<?php echo$warehouse->status==='active'?'success':'secondary'; ?>"><?php echo$warehouse->status==='active'?'Activo':'Inactivo'; ?></span></h1><a href="<?php echo get_uri('warehouses/catalog'); ?>" class="btn btn-default float-end">Volver</a></div><div class="card card-body mb15"><div class="row"><div class="col-md-3"><b>Código</b><br><?php echo esc($warehouse->code); ?></div><div class="col-md-3"><b>Responsable</b><br><?php echo esc($warehouse->responsible_name?:'-'); ?></div><div class="col-md-3"><b>Teléfono</b><br><?php echo esc($warehouse->phone?:'-'); ?></div><div class="col-md-3"><b>Dirección</b><br><?php echo nl2br(esc($warehouse->address?:'-')); ?></div></div></div><div class="card"><div class="card-header"><h4>Existencias</h4></div><div class="table-responsive"><table class="table"><thead><tr><th>Producto</th><th>Código</th><th>Barcode</th><th>Categoría</th><th>Existencia</th></tr></thead><tbody><?php foreach($stocks as$r): ?><tr><td><a href="<?php echo get_uri('warehouses/products/view/'.$r['product_id']); ?>"><?php echo esc($r['name']); ?></a></td><td><?php echo esc($r['internal_code']); ?></td><td><?php echo esc($r['barcode']?:'-'); ?></td><td><?php echo esc($r['category']?:'-'); ?></td><td><?php echo esc(to_decimal_format($r['stock'])); ?></td></tr><?php endforeach; ?></tbody></table></div></div>
